android.extraProguardRules:
-keepattributes *Annotation*
-keepattributes EnclosingMethod
-keepattributes InnerClasses
-keepattributes Signature
-keepattributes SourceFile,LineNumberTable
-keepclassmembers,allowobfuscation class * { @expo.modules.core.interfaces.DoNotStrip *; }
-keepclassmembers,allowobfuscation class * { @com.facebook.proguard.annotations.DoNotStrip *; }
-keepclassmembers,allowobfuscation class * { @com.facebook.react.uimanager.annotations.ReactProp *; }
-keepclassmembers,allowobfuscation class * { @com.facebook.react.uimanager.annotations.ReactPropGroup *; }
-keep class com.facebook.react.turbomodule.** { *; }
-keep class com.facebook.react.bridge.** { *; }
-dontwarn com.facebook.react.**
-keep class com.swmansion.reanimated.** { *; }
-keep class com.swmansion.gesturehandler.** { *; }
-dontwarn com.swmansion.reanimated.**
-keep class expo.modules.** { *; }
-dontwarn expo.modules.**
-dontwarn okhttp3.**
-dontwarn okio.**
-dontwarn androidx.browser.**
